Here is the commit message:
igd-passthrough: fix use of host_pci_config_read

Fix the bug introduced by 595a4f07: function host_pci_config_read() should be
pass-by-reference, not value.
This probably means this function never worked for anyone.

Signed-off-by: Cao jin <caoj.fnst@cn.fujitsu.com>
Reviewed-by: Michael S. Tsirkin <mst@redhat.com>
Signed-off-by: Michael S. Tsirkin <mst@redhat.com>

Here is the root cause:
The bug was caused by the incorrect function signature of `host_pci_config_read`, which was defined to take a `uint32_t` value instead of a pointer to `uint32_t`. This meant that the function could not modify the value passed to it, leading to it not functioning as intended and likely returning incorrect or uninitialized data.

Here is the patch:

-static int host_pci_config_read(int pos, int len, uint32_t val)
+static int host_pci_config_read(int pos, int len, uint32_t *val)
 {
     char path[PATH_MAX];
     int config_fd;
     ssize_t size = sizeof(path);
     /* Access real host bridge. */
     int rc = snprintf(path, size, "/sys/bus/pci/devices/%04x:%02x:%02x.%d/%s",
                       0, 0, 0, 0, "config");
     int ret = 0;

     if (rc >= size || rc < 0) {
         return -ENODEV;
     }

     config_fd = open(path, O_RDWR);
     if (config_fd < 0) {
         return -ENODEV;
     }

     if (lseek(config_fd, pos, SEEK_SET) != pos) {
         ret = -errno;
         goto out;
     }
+
     do {
-        rc = read(config_fd, (uint8_t *)&val, len);
+        rc = read(config_fd, (uint8_t *)val, len);
     } while (rc < 0 && (errno == EINTR || errno == EAGAIN));
     if (rc != len) {
         ret = -errno;
     }
+
 out:
     close(config_fd);
     return ret;
 }

 static int igd_pt_i440fx_initfn(struct PCIDevice *pci_dev)
 {
     uint32_t val = 0;
     int rc, i, num;
     int pos, len;

     num = ARRAY_SIZE(igd_host_bridge_infos);
     for (i = 0; i < num; i++) {
         pos = igd_host_bridge_infos[i].offset;
         len = igd_host_bridge_infos[i].len;
-        rc = host_pci_config_read(pos, len, val);
+        rc = host_pci_config_read(pos, len, &val);
         if (rc) {
             return -ENODEV;
         }
         pci_default_write_config(pci_dev, pos, val, len);
     }

     return 0;
 }



